import React, { useState, useEffect } from 'react';
import {
  Container,
  Box,
  Typography,
  Button,
  Rating,
  Chip,
  Divider,
  Grid,
  Card,
  CardContent,
  IconButton,
  Tabs,
  Tab,
  Avatar,
  Badge,
  Fab,
  Snackbar,
  Alert,
  Breadcrumbs,
  Link,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  ButtonGroup
} from '@mui/material';
import {
  FavoriteBorder,
  Favorite,
  Share,
  ShoppingCart,
  Add,
  Remove,
  NavigateNext,
  LocalShipping,
  Verified,
  Star,
  ExpandMore,
  Visibility,
  CompareArrows,
  ShoppingBag
} from '@mui/icons-material';
import { useParams, useNavigate } from 'react-router-dom';
import { useCart } from '../context/CartContext';

const ProductDetailPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [product, setProduct] = useState(null);
  const [selectedImage, setSelectedImage] = useState(0);
  const [quantity, setQuantity] = useState(1);
  const [selectedSize, setSelectedSize] = useState('');
  const [selectedColor, setSelectedColor] = useState('');
  const [isFavorite, setIsFavorite] = useState(false);
  const [tabValue, setTabValue] = useState(0);
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });

  // Demo product data
  const demoProduct = {
    id: id || '1',
    name: 'Premium Cotton T-Shirt',
    price: 89.99,
    originalPrice: 129.99,
    sale: 30,
    rating: 4.5,
    reviewCount: 256,
    images: [
      'https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?w=500',
      'https://images.unsplash.com/photo-1503341504253-dff4815485f1?w=500',
      'https://images.unsplash.com/photo-1562157873-818bc0726f68?w=500',
      'https://images.unsplash.com/photo-1576566588028-4147f3842f27?w=500'
    ],
    category: 'T-Shirts',
    brand: 'StyleCraft',
    inStock: true,
    stockCount: 15,
    sizes: ['XS', 'S', 'M', 'L', 'XL', 'XXL'],
    colors: ['Black', 'White', 'Navy', 'Gray'],
    description: 'Experience ultimate comfort with our premium cotton t-shirt. Made from 100% organic cotton, this piece combines style with sustainability. Perfect for casual wear or layering.',
    features: [
      '100% Organic Cotton',
      'Pre-shrunk fabric',
      'Tagless for comfort',
      'Double-needle stitching',
      'Machine washable'
    ],
    specifications: {
      'Material': '100% Organic Cotton',
      'Fit': 'Regular',
      'Care': 'Machine wash cold',
      'Origin': 'Made in USA',
      'Weight': '180 GSM'
    },
    reviews: [
      {
        id: 1,
        user: 'Sarah M.',
        rating: 5,
        date: '2024-01-15',
        comment: 'Absolutely love this t-shirt! Super soft and fits perfectly. The quality is amazing.',
        verified: true
      },
      {
        id: 2,
        user: 'Mike R.',
        rating: 4,
        date: '2024-01-10',
        comment: 'Great quality shirt. The fabric is really nice and it washes well.',
        verified: true
      }
    ],
    relatedProducts: [
      { id: '2', name: 'Cotton Polo', price: 79.99, image: 'https://images.unsplash.com/photo-1586790170083-2f9ceadc732d?w=300' },
      { id: '3', name: 'Casual Hoodie', price: 149.99, image: 'https://images.unsplash.com/photo-1556821840-3a63f95609a7?w=300' }
    ]
  };

  useEffect(() => {
    setProduct(demoProduct);
  }, [id]);

  const handleAddToCart = () => {
    if (!selectedSize || !selectedColor) {
      setSnackbar({
        open: true,
        message: 'Please select size and color',
        severity: 'warning'
      });
      return;
    }

    // Add to cart logic here
    setSnackbar({
      open: true,
      message: `Added ${quantity} item(s) to cart`,
      severity: 'success'
    });
  };

  const handleQuantityChange = (change) => {
    const newQuantity = quantity + change;
    if (newQuantity > 0 && newQuantity <= product?.stockCount) {
      setQuantity(newQuantity);
    }
  };

  const handleBuyNow = () => {
    if (!selectedSize || !selectedColor) {
      setSnackbar({
        open: true,
        message: 'Please select size and color',
        severity: 'warning'
      });
      return;
    }
    navigate('/checkout');
  };

  const TabPanel = ({ children, value, index }) => (
    <div hidden={value !== index}>
      {value === index && <Box sx={{ py: 3 }}>{children}</Box>}
    </div>
  );

  if (!product) {
    return (
      <Container sx={{ py: 4, textAlign: 'center' }}>
        <Typography>Loading product...</Typography>
      </Container>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      {/* Breadcrumbs */}
      <Breadcrumbs separator={<NavigateNext fontSize="small" />} sx={{ mb: 3 }}>
        <Link color="inherit" href="/" sx={{ textDecoration: 'none' }}>
          Home
        </Link>
        <Link color="inherit" href="/products" sx={{ textDecoration: 'none' }}>
          Products
        </Link>
        <Link color="inherit" href="/products?category=t-shirts" sx={{ textDecoration: 'none' }}>
          {product.category}
        </Link>
        <Typography color="text.primary">{product.name}</Typography>
      </Breadcrumbs>

      <Grid container spacing={4}>
        {/* Product Images */}
        <Grid item xs={12} md={6}>
          <Box>
            <Card elevation={0} sx={{ borderRadius: 3, overflow: 'hidden', mb: 2, position: 'relative' }}>
              <Box
                component="img"
                src={product.images[selectedImage]}
                alt={product.name}
                sx={{
                  width: '100%',
                  height: { xs: 300, md: 500 },
                  objectFit: 'cover',
                  transition: 'all 0.3s ease'
                }}
              />
              <Box
                sx={{
                  position: 'absolute',
                  top: 16,
                  right: 16,
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 1
                }}
              >
                <IconButton
                  onClick={() => setIsFavorite(!isFavorite)}
                  sx={{
                    backgroundColor: 'white',
                    '&:hover': { backgroundColor: 'rgba(255, 255, 255, 0.9)' }
                  }}
                >
                  {isFavorite ? <Favorite color="error" /> : <FavoriteBorder />}
                </IconButton>
                <IconButton
                  sx={{
                    backgroundColor: 'white',
                    '&:hover': { backgroundColor: 'rgba(255, 255, 255, 0.9)' }
                  }}
                >
                  <Share />
                </IconButton>
              </Box>
              {product.sale > 0 && (
                <Chip
                  label={`${product.sale}% OFF`}
                  color="error"
                  sx={{
                    position: 'absolute',
                    top: 16,
                    left: 16,
                    fontWeight: 'bold'
                  }}
                />
              )}
            </Card>

            {/* Thumbnail Images */}
            <Box sx={{ display: 'flex', gap: 1, overflow: 'auto' }}>
              {product.images.map((image, index) => (
                <Box
                  key={index}
                  component="img"
                  src={image}
                  alt={`${product.name} ${index + 1}`}
                  onClick={() => setSelectedImage(index)}
                  sx={{
                    width: 80,
                    height: 80,
                    objectFit: 'cover',
                    borderRadius: 1,
                    cursor: 'pointer',
                    border: selectedImage === index ? '2px solid #1976d2' : '2px solid transparent',
                    '&:hover': { opacity: 0.7 }
                  }}
                />
              ))}
            </Box>
          </Box>
        </Grid>

        {/* Product Details */}
        <Grid item xs={12} md={6}>
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
              <Chip label={product.brand} variant="outlined" size="small" />
              <Chip label={product.category} variant="outlined" size="small" />
            </Box>

            <Typography variant="h4" fontWeight="bold" sx={{ mb: 1 }}>
              {product.name}
            </Typography>

            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
              <Rating value={product.rating} precision={0.5} readOnly />
              <Typography variant="body2" color="text.secondary">
                ({product.reviewCount} reviews)
              </Typography>
            </Box>

            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 3 }}>
              <Typography variant="h4" fontWeight="bold" color="primary">
                ${product.price}
              </Typography>
              {product.originalPrice && (
                <Typography
                  variant="h6"
                  sx={{ textDecoration: 'line-through', color: 'text.secondary' }}
                >
                  ${product.originalPrice}
                </Typography>
              )}
              {product.sale > 0 && (
                <Chip label={`Save ${product.sale}%`} color="success" size="small" />
              )}
            </Box>

            <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
              {product.description}
            </Typography>

            {/* Stock Status */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 3 }}>
              <Verified color={product.inStock ? 'success' : 'error'} />
              <Typography
                color={product.inStock ? 'success.main' : 'error.main'}
                fontWeight="medium"
              >
                {product.inStock ? `In Stock (${product.stockCount} available)` : 'Out of Stock'}
              </Typography>
            </Box>

            {/* Size Selection */}
            <Box sx={{ mb: 3 }}>
              <Typography variant="h6" fontWeight="medium" sx={{ mb: 1 }}>
                Size
              </Typography>
              <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                {product.sizes.map((size) => (
                  <Button
                    key={size}
                    variant={selectedSize === size ? 'contained' : 'outlined'}
                    size="small"
                    onClick={() => setSelectedSize(size)}
                    sx={{ minWidth: 48 }}
                  >
                    {size}
                  </Button>
                ))}
              </Box>
            </Box>

            {/* Color Selection */}
            <Box sx={{ mb: 3 }}>
              <Typography variant="h6" fontWeight="medium" sx={{ mb: 1 }}>
                Color
              </Typography>
              <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                {product.colors.map((color) => (
                  <Button
                    key={color}
                    variant={selectedColor === color ? 'contained' : 'outlined'}
                    size="small"
                    onClick={() => setSelectedColor(color)}
                  >
                    {color}
                  </Button>
                ))}
              </Box>
            </Box>

            {/* Quantity */}
            <Box sx={{ mb: 4 }}>
              <Typography variant="h6" fontWeight="medium" sx={{ mb: 1 }}>
                Quantity
              </Typography>
              <ButtonGroup variant="outlined">
                <IconButton onClick={() => handleQuantityChange(-1)} disabled={quantity <= 1}>
                  <Remove />
                </IconButton>
                <Button disabled sx={{ minWidth: 60 }}>
                  {quantity}
                </Button>
                <IconButton
                  onClick={() => handleQuantityChange(1)}
                  disabled={quantity >= product.stockCount}
                >
                  <Add />
                </IconButton>
              </ButtonGroup>
            </Box>

            {/* Action Buttons */}
            <Box sx={{ display: 'flex', gap: 2, mb: 4, flexWrap: 'wrap' }}>
              <Button
                variant="contained"
                size="large"
                onClick={handleAddToCart}
                startIcon={<ShoppingCart />}
                disabled={!product.inStock}
                sx={{ flex: 1, minWidth: 200 }}
              >
                Add to Cart
              </Button>
              <Button
                variant="outlined"
                size="large"
                onClick={handleBuyNow}
                startIcon={<ShoppingBag />}
                disabled={!product.inStock}
                sx={{ flex: 1, minWidth: 200 }}
              >
                Buy Now
              </Button>
            </Box>

            {/* Features */}
            <Box sx={{ mb: 3 }}>
              <Typography variant="h6" fontWeight="medium" sx={{ mb: 2 }}>
                Features
              </Typography>
              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                {product.features.map((feature, index) => (
                  <Chip key={index} label={feature} variant="outlined" size="small" />
                ))}
              </Box>
            </Box>

            {/* Shipping Info */}
            <Card sx={{ bgcolor: 'grey.50', mb: 3 }}>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <LocalShipping color="primary" />
                  <Typography variant="body2" fontWeight="medium">
                    Free shipping on orders over $75 | Easy returns within 30 days
                  </Typography>
                </Box>
              </CardContent>
            </Card>
          </Box>
        </Grid>
      </Grid>

      {/* Product Details Tabs */}
      <Box sx={{ mt: 6 }}>
        <Tabs value={tabValue} onChange={(e, newValue) => setTabValue(newValue)}>
          <Tab label="Description" />
          <Tab label="Specifications" />
          <Tab label={`Reviews (${product.reviewCount})`} />
        </Tabs>

        <TabPanel value={tabValue} index={0}>
          <Typography variant="body1" paragraph>
            {product.description}
          </Typography>
          <Typography variant="h6" gutterBottom>
            Key Features:
          </Typography>
          <ul>
            {product.features.map((feature, index) => (
              <li key={index}>
                <Typography variant="body1">{feature}</Typography>
              </li>
            ))}
          </ul>
        </TabPanel>

        <TabPanel value={tabValue} index={1}>
          <Grid container spacing={2}>
            {Object.entries(product.specifications).map(([key, value]) => (
              <Grid item xs={12} sm={6} key={key}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', py: 1 }}>
                  <Typography fontWeight="medium">{key}:</Typography>
                  <Typography color="text.secondary">{value}</Typography>
                </Box>
                <Divider />
              </Grid>
            ))}
          </Grid>
        </TabPanel>

        <TabPanel value={tabValue} index={2}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 3 }}>
            <Typography variant="h5">{product.rating}</Typography>
            <Rating value={product.rating} precision={0.5} readOnly size="large" />
            <Typography color="text.secondary">
              Based on {product.reviewCount} reviews
            </Typography>
          </Box>

          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
            {product.reviews.map((review) => (
              <Card key={review.id} variant="outlined">
                <CardContent>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
                    <Avatar sx={{ width: 40, height: 40 }}>
                      {review.user.charAt(0)}
                    </Avatar>
                    <Box sx={{ flex: 1 }}>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Typography fontWeight="medium">{review.user}</Typography>
                        {review.verified && <Verified color="success" fontSize="small" />}
                      </Box>
                      <Rating value={review.rating} size="small" readOnly />
                    </Box>
                    <Typography variant="caption" color="text.secondary">
                      {review.date}
                    </Typography>
                  </Box>
                  <Typography variant="body2">{review.comment}</Typography>
                </CardContent>
              </Card>
            ))}
          </Box>
        </TabPanel>
      </Box>

      {/* Related Products */}
      <Box sx={{ mt: 6 }}>
        <Typography variant="h5" fontWeight="bold" sx={{ mb: 3 }}>
          You Might Also Like
        </Typography>
        <Grid container spacing={3}>
          {product.relatedProducts.map((relatedProduct) => (
            <Grid item xs={12} sm={6} md={4} key={relatedProduct.id}>
              <Card
                sx={{
                  cursor: 'pointer',
                  transition: 'transform 0.2s',
                  '&:hover': { transform: 'translateY(-4px)' }
                }}
                onClick={() => navigate(`/products/${relatedProduct.id}`)}
              >
                <Box
                  component="img"
                  src={relatedProduct.image}
                  alt={relatedProduct.name}
                  sx={{ width: '100%', height: 200, objectFit: 'cover' }}
                />
                <CardContent>
                  <Typography variant="h6" noWrap>
                    {relatedProduct.name}
                  </Typography>
                  <Typography variant="h6" color="primary" fontWeight="bold">
                    ${relatedProduct.price}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Box>

      {/* Floating Cart Button */}
      <Fab
        color="primary"
        sx={{
          position: 'fixed',
          bottom: 16,
          right: 16,
          display: { xs: 'flex', md: 'none' }
        }}
        onClick={handleAddToCart}
      >
        <ShoppingCart />
      </Fab>

      {/* Snackbar */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={3000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
      >
        <Alert severity={snackbar.severity} onClose={() => setSnackbar({ ...snackbar, open: false })}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Container>
  );
};

export default ProductDetailPage;
